export type NavigationLoadingOutcome =
  /**  The declaration was not attempted, including when selection facts explain its absence. */
  | "not-attempted"
  /**  The selected local resource was absent from the provider. */
  | "missing-resource"
  /**  The provider failed while reading the selected resource. */
  | "read-failed"
  /**  XML encoding detection or decoding failed. */
  | "invalid-encoding"
  /**  The decoded document was not usable EPUB NAV or NCX. */
  | "malformed"
  /**  The selected document loaded successfully. */
  | "loaded";

/**
 *  One entry in a navigation list, with its label and where it points.
 *
 *  Building one requires a label. Parsing does not: a book with an unlabelled entry still
 *  produces one here.
 *
 *  ```compile_fail
 *  use epub_stack::navigation::NavigationPoint;
 *
 *  // Bon's typestate rejects construction without the required label.
 *  let _ = NavigationPoint::builder().build();
 *  ```
 */
export type NavigationPoint = {
  label: EpubString | null;
  authoredHref: AuthoredHref | null;
  children: NavigationPoint[];
  hidden: boolean;
  semantic: EpubStructuralSemantic | null;
  authoredSemanticTokens: SemanticToken[];
};

/**  The syntax of a selected navigation document. */
export type NavigationSource =
  /**  EPUB 3 navigation XHTML. */
  | "epub-nav"
  /**  EPUB 2 Navigation Center eXtended. */
  | "ncx";

/**  Resolved outcome of one authored navigation href. */
export type NavigationTarget =
  /**  The navigation point omitted its href. */
  | { state: "missing-href" }
  /**  The href resolved to a resource in this snapshot. */
  | {
      state: "resource";
      /**  Matching physical resource in this snapshot. */
      resource: ResourceOrdinal;
      /**  Decoded non-empty fragment, when authored. */
      fragment: string | null;
    }
  /**  The href resolved to a local path with no indexed resource. */
  | {
      state: "missing-resource";
      /**  Resolved local path. */
      path: EpubPath;
      /**  Decoded non-empty fragment, when authored. */
      fragment: string | null;
    }
  /**  The href resolved to a valid non-local address with no indexed resource. */
  | {
      state: "unindexed-address";
      /**  Resolved remote, data, or other external address. */
      address: ResourceAddress;
      /**  Decoded non-empty fragment, when authored. */
      fragment: string | null;
    }
  /**  The authored href could not be resolved, including against an authored base. */
  | { state: "invalid" };

/**  One navigation point's authored href and resolved target in deterministic document order. */
export type NavigationTargetFacts = {
  /**  Zero-based navigation-list position. */
  listIndex: number;
  /**  Point indices from the list root to this point. */
  pointPath: number[];
  /**  Exact authored href, when present. */
  authoredHref: AuthoredHref | null;
  /**  Resolution against the selected navigation document path and resource inventory. */
  target: NavigationTarget;
};

/**
 *  An owned EPUB 2 `meta` name/content pair.
 *
 *  Parsed instances may represent a missing side of the pair.
 */
export type Opf2Meta = {
  name: EpubString | null;
  content: string | null;
};

/**
 *  The semantic projection of an OPF package document.
 *
 *  Preserves order within modeled groups, authored tokens, and hrefs, but not unknown XML or
 *  source formatting.
 */
export type Package = {
  uniqueIdentifierId: EpubString | null;
  version: EpubVersion | null;
  xmlLang: EpubString | null;
  id: EpubString | null;
  dir: TextDirection | null;
  prefix: EpubString | null;
  metadata: Metadata;
  manifest: Manifest;
  spine: Spine;
  guide: Guide | null;
  collections: Collection[];
};

/**  Reading progression accepted by the spine `page-progression-direction` attribute. */
export type PageProgressionDirection =
  /**  Pages progress from left to right. */
  | "ltr"
  /**  Pages progress from right to left. */
  | "rtl"
  /**  The reading system chooses its default progression. */
  | "default";

/**  A current EPUB synthetic page-spread placement projected from an itemref property. */
export type PageSpread =
  /**  Places the page on the left side of a synthetic spread. */
  | "left"
  /**  Places the page on the right side of a synthetic spread. */
  | "right"
  /**  Centers the page across a synthetic spread. */
  | "center";

/**  Whether a resolved resource address has corresponding provider bytes. */
export type ProviderPresence =
  /**  The local path appeared in the complete provider index. */
  | {
      state: "present";
      /**  Provider-reported byte length, encoded as a decimal string for JSON safety. */
      sizeBytes: string | null;
    }
  /**  The local path did not appear in the complete provider index. */
  | { state: "missing" }
  /**  Provider membership does not apply to a non-local address. */
  | { state: "not-applicable" };

/**  One coherent view of a publication's structure, borrowed from the open publication. */
export type PublicationFacts = {
  /**  Complete modeled OPF package structure. */
  package: Package;
  /**  Selected normalized EPUB NAV or NCX structure. */
  navigation: NavigationDocument | null;
  /**  Resource inventory and resolution outcomes aligned with the package structure. */
  resources: ResourceIndex;
  /**  Navigation acquisition observations aligned with the same state. */
  navigationLoading: NavigationLoadingFacts;
  /**  Navigation targets in list order and depth-first point order. */
  navigationTargets: NavigationTargetFacts[];
};

export type ReadingOrderOccurrence = {
  idref: AuthoredIdRef | null;
  target: IdrefTarget | null;
  resource: ResourceOrdinal | null;
  linear: Linear;
  presentation: ReadingOrderPresentation;
};

/**
 *  Occurrence-owned authored presentation state for one reading-order entry.
 *
 *  Rendition settings retain provenance, ambiguity, malformed source values, and itemref
 *  precedence. Only a recognized itemref token overrides package metadata; see
 *  [`RenditionSetting`]. Page progression is copied from the spine and preserves an authored
 *  `default`; absent values and reading-system defaults remain absent.
 */
export type ReadingOrderPresentation = {
  layout: RenditionSetting<RenditionLayout>;
  flow: RenditionSetting<RenditionFlow>;
  orientation: RenditionSetting<RenditionOrientation>;
  spread: RenditionSetting<RenditionSpread>;
  pageSpread: RenditionSetting<PageSpread>;
  pageProgressionDirection: PageProgressionDirection | null;
  alignXCenter: boolean;
};

/**
 *  A modeled EPUB 2 guide reference.
 *
 *  The authored href spelling is retained separately from its usable [`EpubHref`] projection.
 */
export type Reference = {
  referenceType: ReferenceType | null;
  title: EpubString | null;
  href: AuthoredHref | null;
};

/**  A recognized EPUB 2 guide reference type, or an owned unknown token. */
export type ReferenceType =
  /**  The publication cover. */
  | "cover"
  /**  The title page. */
  | "title-page"
  /**  The table of contents. */
  | "toc"
  /**  An index. */
  | "index"
  /**  A glossary. */
  | "glossary"
  /**  Acknowledgements. */
  | "acknowledgements"
  /**  A bibliography. */
  | "bibliography"
  /**  A colophon. */
  | "colophon"
  /**  A copyright page. */
  | "copyright-page"
  /**  A dedication. */
  | "dedication"
  /**  An epigraph. */
  | "epigraph"
  /**  A foreword. */
  | "foreword"
  /**  A list of illustrations. */
  | "loi"
  /**  A list of tables. */
  | "lot"
  /**  Notes. */
  | "notes"
  /**  A preface. */
  | "preface"
  /**  The publication's main text. */
  | "text"
  /**  An unrecognized authored type token, preserved as owned text. */
  | { other: string };

/**
 *  One authored rendition value and its optional recognized semantic projection.
 *
 *  Package metadata can omit content, so [`Self::authored_value`] and [`Self::value`] are
 *  independent. Itemref candidates retain the complete property token spelling as their authored
 *  value.
 */
export type RenditionCandidate<T> = {
  source: RenditionValueSource;
  authoredValue: EpubString | null;
  value: T | null;
};

/**
 *  An authored `rendition:flow` value retained for historical EPUB inspection.
 *
 *  EPUB 3.4 classifies this rendition control as outdated. It represents source metadata, not
 *  application or reading-system runtime policy.
 */
export type RenditionFlow =
  /**  The author expressed no flow preference. */
  | "auto"
  /**  The author preferred dynamic pagination. */
  | "paginated"
  /**  The author preferred continuous scrolling across spine items. */
  | "scrolled-continuous"
  /**  The author preferred separately scrolled spine items. */
  | "scrolled-doc";

/**  A recognized EPUB rendition layout value. */
export type RenditionLayout =
  /**  Content participates in dynamic pagination or scrolling. */
  | "reflowable"
  /**  Content uses author-defined page geometry. */
  | "pre-paginated"
  /**  Content uses the EPUB 3.4 continuous `roll` layout. */
  | "roll";

/**
 *  An authored `rendition:orientation` value retained for historical EPUB inspection.
 *
 *  EPUB 3.4 classifies this rendition control as outdated. It represents source metadata, not
 *  application or reading-system runtime policy.
 */
export type RenditionOrientation =
  /**  The author left orientation selection to the reading system. */
  | "auto"
  /**  The author preferred landscape orientation. */
  | "landscape"
  /**  The author preferred portrait orientation. */
  | "portrait";

/**
 *  Authored state of one rendition presentation setting.
 *
 *  Candidate count is retained without deduplication: repeated declarations are ambiguous even
 *  when they project to the same typed value. No reading-system defaults are synthesized.
 *
 *  For the metadata-backed families, only a recognized itemref property token overrides package
 *  metadata. An unrecognized token spelled like one of them, such as
 *  `rendition:layout-prepaginated`, leaves the publication-level setting in force; its authored
 *  spelling remains available through the occurrence's property tokens.
 */
export type RenditionSetting<T> =
  /**  No applicable itemref property or package metadata was authored. */
  | { state: "unspecified" }
  /**  Exactly one applicable candidate was authored. */
  | {
      state: "specified";
      /**  The unique authored candidate. */
      value: RenditionCandidate<T>;
    }
  /**  More than one applicable candidate was authored, in source order. */
  | {
      state: "ambiguous";
      /**  All authored candidates responsible for the ambiguity. */
      value: RenditionCandidate<T>[];
    };

/**
 *  An authored `rendition:spread` value retained for historical EPUB inspection.
 *
 *  EPUB 3.4 classifies this rendition control as outdated. It represents source metadata, not
 *  application or reading-system runtime policy.
 */
export type RenditionSpread =
  /**  The author left synthetic-spread selection to the reading system. */
  | "auto"
  /**  The author preferred spreads in both orientations. */
  | "both"
  /**  The author preferred spreads only in landscape orientation. */
  | "landscape"
  /**  The author preferred no synthetic spreads. */
  | "none"
  /**  The author preferred spreads only in portrait orientation. */
  | "portrait";

/**  The authored source of a rendition presentation candidate. */
export type RenditionValueSource =
  /**  The candidate came from an unrefined package metadata `meta` element. */
  | "package-metadata"
  /**  The candidate came from a spine `itemref` property token. */
  | "item-ref-property";

/**  Where a resource lives: a path in the container, or a URL the book points out to. */
export type ResourceAddress =
  /**  A canonical path in the publication provider. */
  | {
      kind: "local";
      /**  Canonical provider-relative path. */
      value: EpubPath;
    }
  /**  An HTTP(S) or scheme-relative URL. */
  | {
      kind: "remote";
      /**  Remote URL text excluding any fragment. */
      value: string;
    }
  /**  A `data:` URL retained as authored. */
  | {
      kind: "data";
      /**  Exact authored data URL. */
      value: string;
    }
  /**  A syntactically valid URL using another scheme. */
  | {
      kind: "external";
      /**  Authored URL using another scheme, excluding any fragment. */
      value: string;
    };

/**
 *  Everything the publication declares and everything the container holds, resolved against
 *  each other.
 *
 *  Two declarations of the same file are one resource.
 */
export type ResourceIndex = {
  packagePath: EpubPath;
  coverPath: EpubPath | null;
  resources: ResourceRecord[];
  declarations: ManifestDeclaration[];
  readingOrder: ReadingOrderOccurrence[];
  selections: ResourceSelections;
};

/** Where a resource sits in a [`ResourceIndex`]. */
export type ResourceOrdinal = number;

export type ResourceRecord = {
  address: ResourceAddress;
  presence: ProviderPresence;
  declarations: ManifestOrdinal[];
  hasXhtmlDeclaration: boolean;
  hasStylesheetDeclaration: boolean;
  hasSvgDeclaration: boolean;
  scripted: boolean;
};

/**  Explicit structural-resource selection outcome. */
export type ResourceSelection =
  /**  No applicable authored selection evidence exists. */
  | { state: "absent" }
  /**  One declaration or direct resource was selected. */
  | {
      state: "selected";
      /**  Relationship responsible for the selection. */
      source: SelectionSource;
      /**  Selected declaration, absent for the directly selected package resource. */
      declaration: ManifestOrdinal | null;
      /**  Resolved resource, absent when a selected declaration has no usable href. */
      resource: ResourceOrdinal | null;
    }
  /**  An authored ID relationship matched no declaration. */
  | {
      state: "unresolved-authored-id";
      /**  Relationship containing the unresolved ID. */
      source: SelectionSource;
      /**  Exact modeled authored ID text. */
      authoredId: string;
    }
  /**  More than one declaration satisfies the authored selection relationship. */
  | {
      state: "ambiguous";
      /**  Relationship responsible for the ambiguity. */
      source: SelectionSource;
      /**  Candidate declaration ordinals in manifest order. */
      candidates: ManifestOrdinal[];
    };

/**  Explicit outcomes for publication structural-resource selections. */
export type ResourceSelections = {
  /**  Selected package document. */
  package?: ResourceSelection;
  /**  Selected cover image. */
  cover?: ResourceSelection;
  /**  Selected EPUB navigation document declaration. */
  epubNav?: ResourceSelection;
  /**  Selected EPUB 2 NCX declaration. */
  ncx?: ResourceSelection;
};

/**  Authored relationship used to select a structural resource. */
export type SelectionSource =
  /**  The package path supplied when opening the rendition. */
  | "package-path"
  /**  The manifest `nav` property. */
  | "epub-nav-property"
  /**  The manifest `cover-image` property. */
  | "cover-image-property"
  /**  EPUB 2 `meta name="cover"` metadata. */
  | "opf2-cover-metadata"
  /**  The spine `toc` attribute. */
  | "spine-toc";

/**  One authored or native token that establishes structural meaning. */
export type SemanticToken =
  /**  One whitespace-separated `epub:type` token. */
  | {
      source: "epub-type";
      /**  The authored token and its recognized EPUB structural meaning. */
      token: VocabToken<EpubStructuralSemantic>;
    }
  /**  One whitespace-separated ARIA `role` token. */
  | {
      source: "aria-role";
      /**  The authored token and its recognized DPUB role. */
      token: VocabToken<DpubAriaRole>;
    }
  /**  One whitespace-separated NCX `class` token. */
  | {
      source: "ncx-class";
      /**  The exact token spelling. */
      token: EpubString;
    }
  /**  Native semantics contributed by an HTML element itself. */
  | {
      source: "html-element";
      /**  The element's structural meaning. */
      element: HtmlStructuralElement;
    };

/**  An OPF spine and its itemrefs in reading order. */
export type Spine = {
  id: EpubString | null;
  pageProgressionDirection: PageProgressionDirection | null;
  toc: string | null;
  itemrefs: ItemRef[];
};

/**  Text direction accepted by EPUB `dir` attributes. */
export type TextDirection =
  /**  Left-to-right text. */
  | "ltr"
  /**  Right-to-left text. */
  | "rtl"
  /**  Direction inferred from the text. */
  | "auto";

/**
 *  One vocabulary token retaining its authored spelling and optional known projection.
 *
 *  Recognition follows the term type's [`FromStr`]: ASCII case-insensitive for EPUB package
 *  vocabularies, case-sensitive for compact URL references such as
 *  [`EpubStructuralSemantic`](crate::semantics::EpubStructuralSemantic). Unknown terms are
 *  preserved exactly and reported by [`Self::as_str`] with no known value.
 */
export type VocabToken<K> = {
  raw: EpubString;
  known: K | null;
};
